(() => {
'use strict';
const original=structuredClone(window.WEDDING),key='amour-wedding-draft-v1';
const clone=x=>structuredClone(x),$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={aesthetic1Alt:'Описание фото эстетики 1',aesthetic2Alt:'Описание фото эстетики 2',aesthetic3Alt:'Описание фото эстетики 3',aesthetic4Alt:'Описание фото эстетики 4',couple:'Вы и ваша история',first:'Имя жениха / первого партнёра',second:'Имя невесты / второго партнёра',initials:'Инициалы в шапке',event:'Дата и время',date:'Дата свадьбы',time:'Время начала',timezone:'Часовой пояс (например, +03:00)',city:'Город',deadline:'Ответить до',hero:'Первый экран',eyebrow:'Подпись над заголовком',title:'Заголовок',accent:'Вторая строка заголовка',caption:'Подпись',photoNote:'Подпись на фотографии',invitationLabel:'Надпись внизу первого экрана',button:'Текст кнопки',scroll:'Подсказка прокрутки',stamp:'Надпись на печати',intro:'Приглашение',text:'Текст',footnote:'Заключительная фраза',photos:'Фотографии',heroAlt:'Описание главного фото',storyAlt:'Описание фото истории',detailAlt:'Описание дополнительного фото',registryAlt:'Описание фото ЗАГСа',venueAlt:'Описание фото банкетного зала',registry:'ЗАГС',venue:'Банкетный зал',name:'Название',address:'Адрес',note:'Дополнение',mapUrl:'Ссылка на карту',mapLabel:'Текст кнопки карты',schedule:'Программа дня',items:'Пункты',icon:'Иконка',dress:'Дресс-код',colors:'Цвета палитры',details:'Пожелания гостям',countdown:'Обратный отсчёт',after:'Текст после наступления даты',countdownLabels:'Подписи счётчика',rsvp:'Анкета гостя',delivery:'Способ получения ответов',googleScriptUrl:'Адрес Google Apps Script для сохранения ответов',nameLabel:'Подпись поля имени',namePlaceholder:'Пример имени',partnerLabel:'Подпись поля спутника',partnerPlaceholder:'Подсказка поля спутника',attendanceLabel:'Вопрос о присутствии',yesLabel:'Ответ «Да»',noLabel:'Ответ «Нет»',noteLabel:'Подпись поля пожеланий',notePlaceholder:'Подсказка поля пожеланий',email:'Email для ответов гостей',formUrl:'Ссылка на внешнюю анкету (необязательно)',externalLabel:'Кнопка внешней анкеты',downloadNote:'Пояснение при сохранении ответа в файл',emailNote:'Пояснение при отправке по почте',privacy:'Пояснение под формой',footer:'Завершение',small:'Мелкая подпись внизу',theme:'Цвета сайта',background:'Фон страницы',ink:'Основной текст'};
const groups=[{id:'general',name:'Основное',keys:['couple','event']},{id:'photos',name:'Фотографии',keys:['photos']},{id:'texts',name:'Тексты',keys:['hero','intro','countdown','footer']},{id:'registry',name:'ЗАГС',keys:['registry']},{id:'venue',name:'Банкетный зал',keys:['venue']},{id:'schedule',name:'Программа',keys:['schedule']},{id:'details',name:'Детали',keys:['dress','details']},{id:'theme',name:'Цвета',keys:['theme']},{id:'rsvp',name:'Анкета',keys:['rsvp']}];
let active='general',state=clone(original),saveTimer,toastTimer;
function validate(value,base,path=''){if(Array.isArray(base)){if(!Array.isArray(value)||value.length<1||value.length>16)throw Error('В списках должно быть от 1 до 16 элементов.');return value.map(v=>validate(v,base[0],path));}if(base&&typeof base==='object'){if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Неверный формат настроек.');const out={};for(const k of Object.keys(base))out[k]=Object.hasOwn(value,k)?validate(value[k],base[k],path+'.'+k):clone(base[k]);return out;}if(path==='.rsvp.delivery'&&!['googleSheets','email','download'].includes(value))throw Error('Выберите способ получения ответов.');if(path==='.rsvp.googleScriptUrl'&&value&&!/^https:\/\/script\.google\.com\/macros\/s\/[A-Za-z0-9_-]+\/exec$/.test(value))throw Error('Вставьте адрес веб-приложения Google Apps Script, заканчивающийся на /exec.');if(typeof value!=='string'||value.length>5000000)throw Error('В настройках допустимы только текстовые значения.');if(path.startsWith('.photos.')&&!path.endsWith('Alt')&&value&&!/^(data:image\/(jpeg|png|webp|gif);base64,|https?:\/\/|(?:\.\/)?assets\/)/i.test(value))throw Error('Для фото используйте загрузку или ссылку https://.');if((path==='.event.date'||path==='.event.deadline')&&(!/^\d{4}-\d{2}-\d{2}$/.test(value)||Number.isNaN(new Date(value+'T12:00:00Z').valueOf())))throw Error('Укажите корректную дату.');if(path==='.event.time'&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(value))throw Error('Время должно быть в формате ЧЧ:ММ.');if(path==='.event.timezone'&&!/^[+-](0\d|1[0-4]):[0-5]\d$/.test(value))throw Error('Часовой пояс должен быть в формате +03:00.');if((path.startsWith('.theme.')||path==='.dress.colors')&&!/^#[\da-f]{6}$/i.test(value))throw Error('Цвет должен быть в формате #890d27.');if(path==='.rsvp.email'&&value&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value))throw Error('Проверьте email для ответов.');if((path==='.rsvp.formUrl'||path==='.venue.mapUrl'||path==='.registry.mapUrl')&&value&&!/^https?:\/\//i.test(value))throw Error('Ссылка должна начинаться с https://.');return value;}
try{const draft=localStorage.getItem(key);if(draft){state=validate(JSON.parse(draft),original);$('#save-status').textContent='Загружен ваш черновик';}}catch{$('#save-status').textContent='Открыт исходный шаблон';}
const get=path=>path.split('.').reduce((o,k)=>o[k],state);
const set=(path,value)=>{const parts=path.split('.'),last=parts.pop();parts.reduce((o,k)=>o[k],state)[last]=value;};
function toast(message){const el=$('#toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.hidden=true;},6500);}
function sync(){const frame=$('#preview');frame.contentWindow.postMessage({type:'wedding-preview',content:state},location.origin==='null'?'*':location.origin);}
function changed(){sync();$('#save-status').textContent='Сохраняем черновик…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>{try{localStorage.setItem(key,JSON.stringify(state));$('#save-status').textContent='Черновик сохранён в этом браузере';}catch{$('#save-status').textContent='Не хватает места. Сохраните настройки в файл.';}},300);}
function field(path,value){const prop=path.split('.').at(-1),isPhoto=path.startsWith('photos.')&&!prop.endsWith('Alt');let label=labels[prop]||prop;if(isPhoto)label={hero:'Первый экран',story:'История — основное фото',detail:'История — маленькое фото',registry:'Фотография ЗАГСа',venue:'Фотография банкетного зала',aesthetic1:'Эстетика — фото 1 из 4',aesthetic2:'Эстетика — фото 2 из 4',aesthetic3:'Эстетика — фото 3 из 4',aesthetic4:'Эстетика — фото 4 из 4'}[prop];if(path==='theme.accent')label='Акцентный цвет';if(path==='hero.accent'||path==='intro.accent')label='Вторая строка заголовка';if(path==='countdown.labels')label='Подписи счётчика';
if(Array.isArray(value)){const primitive=typeof value[0]==='string';return `<div class="edit-field">${esc(label)}</div><div class="array-group">${value.map((v,i)=>primitive?`<div class="array-item"><div class="array-item-title"><span>${i+1}</span><button type="button" data-remove="${path}" data-index="${i}" aria-label="Удалить элемент ${i+1}">Удалить</button></div>${field(path+'.'+i,v)}</div>`:`<div class="array-item"><div class="array-item-title"><span>Пункт ${i+1}</span><div><button type="button" data-up="${path}" data-index="${i}" aria-label="Переместить пункт ${i+1} вверх">↑</button><button type="button" data-down="${path}" data-index="${i}" aria-label="Переместить пункт ${i+1} вниз">↓</button><button type="button" data-remove="${path}" data-index="${i}" aria-label="Удалить пункт ${i+1}">Удалить</button></div></div>${Object.entries(v).map(([k,x])=>field(path+'.'+i+'.'+k,x)).join('')}</div>`).join('')}<button type="button" class="add-button" data-add="${path}">+ Добавить ${primitive?'элемент':'пункт'}</button></div>`;}
if(value&&typeof value==='object')return Object.entries(value).map(([k,v])=>field(path+'.'+k,v)).join('');
if(isPhoto)return `<div class="edit-field">${esc(label)}<img class="image-preview" data-preview-image="${path}" src="${esc(value)}" alt="Предпросмотр фотографии"><label class="upload-label">Загрузить фотографию<input type="file" accept="image/jpeg,image/png,image/webp" data-upload="${path}" hidden></label><label class="edit-field">Или ссылка на изображение<input type="url" data-path="${path}" value="${esc(value.startsWith('data:')?'':value)}" placeholder="https://…"></label></div>`;
const isColor=path.startsWith('theme.')||path.startsWith('dress.colors.'),isDate=['event.date','event.deadline'].includes(path),isTime=path==='event.time',isLong=value.length>100||['text','caption','footnote','downloadNote','emailNote','privacy'].includes(prop);
const input=path==='rsvp.delivery'?`<select data-path="${path}">${[['googleSheets','Google Таблица'],['email','Письмо по email'],['download','Скачать ответ в файл']].map(([v,l])=>`<option value="${v}" ${value===v?'selected':''}>${l}</option>`).join('')}</select>`:prop==='icon'?`<select data-path="${path}">${[['glasses','Бокалы'],['plate','Ужин'],['cake','Торт'],['sparkles','Искры'],['car','Машина'],['sun','Солнце']].map(([v,l])=>`<option value="${v}" ${value===v?'selected':''}>${l}</option>`).join('')}</select>`:isLong?`<textarea data-path="${path}" rows="3">${esc(value)}</textarea>`:`<input data-path="${path}" type="${isColor?'color':isDate?'date':isTime?'time':prop==='email'?'email':prop.endsWith('Url')?'url':'text'}" value="${esc(value)}">`;
const help=path==='rsvp.googleScriptUrl'?'Вставьте адрес развёрнутого веб-приложения вида https://script.google.com/macros/s/…/exec. Инструкция: google-apps-script/SETUP.md.':path==='rsvp.delivery'?'Для Google Таблицы нужен адрес Google Apps Script ниже. Внешняя анкета, если указана, заменяет встроенную форму.':(path==='registry.mapUrl'||path==='venue.mapUrl')?'Если оставить поле пустым, кнопка «Как добраться» откроет поиск на Яндекс Картах по адресу и городу. Пока адрес ЗАГСа уточняется, показывается поиск ЗАГСов в вашем городе.':path==='rsvp.email'?'При заполнении анкета подготовит письмо. Гость отправляет его в своей почте.':path==='rsvp.formUrl'?'Ссылка на Яндекс Формы, Google Forms или другой сервис заменит встроенную анкету.':path==='rsvp.text'?'Используйте {deadline}, чтобы автоматически подставить крайний срок.':path==='event.timezone'?'Москва: +03:00. Используется для точного обратного отсчёта.':'';
return `<label class="edit-field">${esc(/^\d+$/.test(prop)?'Значение':label)}${input}${help?`<span class="field-help">${esc(help)}</span>`:''}</label>`;}
function draw(){const group=groups.find(g=>g.id===active);$('#tabs').innerHTML=groups.map(g=>`<button data-tab="${g.id}" class="${g.id===active?'active':''}" aria-current="${g.id===active?'true':'false'}">${g.name}</button>`).join('');$('#fields').innerHTML=group.keys.map(k=>`<section class="fields-section"><h2>${labels[k]}</h2>${typeof state[k]==='object'&&!Array.isArray(state[k])?Object.entries(state[k]).map(([sub,val])=>field(k+'.'+sub,val)).join(''):field(k,state[k])}</section>`).join('');}
$('#tabs').addEventListener('click',e=>{const tab=e.target.closest('[data-tab]');if(tab){active=tab.dataset.tab;draw();}});
$('#fields').addEventListener('input',e=>{const path=e.target.dataset.path;if(!path)return;set(path,e.target.value);if(path.startsWith('photos.')){const img=$(`[data-preview-image="${path}"]`);if(img)img.src=e.target.value;}changed();});
$('#fields').addEventListener('click',e=>{const btn=e.target.closest('button');if(!btn)return;for(const action of ['add','remove','up','down']){const path=btn.dataset[action];if(!path)continue;const array=get(path),i=Number(btn.dataset.index);if(action==='add'){if(array.length>=16)return toast('В этом списке может быть до 16 элементов.');const item=clone(array.at(-1));array.push(item);}else if(action==='remove'){if(array.length===1)return toast('Оставьте хотя бы один элемент.');array.splice(i,1);}else{const dest=action==='up'?i-1:i+1;if(dest<0||dest>=array.length)return;[array[i],array[dest]]=[array[dest],array[i]];}draw();changed();break;}});
$('#fields').addEventListener('change',async e=>{const path=e.target.dataset.upload;if(!path)return;const file=e.target.files[0];if(!file)return;if(!/^image\/(png|jpeg|webp)$/.test(file.type))return toast('Выберите фотографию JPG, PNG или WebP.');if(file.size>20*1024*1024)return toast('Выберите фото размером до 20 МБ.');try{const bitmap=await createImageBitmap(file);const ratio=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));const ctx=canvas.getContext('2d');ctx.fillStyle='#f4f1eb';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();set(path,canvas.toDataURL('image/jpeg',.86));draw();changed();toast('Фотография обновлена.');}catch{toast('Не удалось прочитать фотографию. Попробуйте другой файл.');}});
$('.device-buttons').addEventListener('click',e=>{const btn=e.target.closest('[data-device]');if(!btn)return;$('.preview-stage').classList.toggle('mobile',btn.dataset.device==='mobile');document.querySelectorAll('[data-device]').forEach(b=>{b.classList.toggle('active',b===btn);b.setAttribute('aria-pressed',String(b===btn));});});
window.addEventListener('message',e=>{if(e.source===$('#preview').contentWindow&&e.origin===location.origin&&e.data?.type==='wedding-ready')sync();});$('#preview').addEventListener('load',sync);
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),15000);}
const json=c=>JSON.stringify(c,null,2).replace(/</g,'\\u003c');
function checked(){try{return validate(state,original);}catch(error){toast(error.message);return null;}}
$('#save-json').addEventListener('click',()=>{const c=checked();if(c){download('wedding-settings.json',JSON.stringify(c,null,2),'application/json');toast('Настройки сохранены. Их можно импортировать для другой свадьбы.');}});
$('#save-config').addEventListener('click',()=>{const c=checked();if(c){download('content.js','window.WEDDING = '+json(c)+';','text/javascript');toast('Замените dist/content.js этим файлом и обновите сайт на хостинге.');}});
$('#import-button').addEventListener('click',()=>$('#import-file').click());
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>22*1024*1024)throw Error('Файл настроек слишком большой.');state=validate(JSON.parse(await file.text()),original);draw();changed();toast('Настройки загружены.');}catch(error){toast('Импорт: '+error.message);}finally{e.target.value='';}});
$('#reset').addEventListener('click',()=>{if(!confirm('Вернуть исходное наполнение? Сначала сохраните настройки, если хотите вернуться к ним позже.'))return;state=clone(original);draw();changed();toast('Исходный шаблон восстановлен.');});
async function readText(path){const r=await fetch(path);if(!r.ok)throw Error('Не удалось прочитать '+path);return r.text();}
function toData(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});}
$('#export-site').addEventListener('click',async()=>{const c=checked();if(!c)return;const btn=$('#export-site'),old=btn.innerHTML;btn.disabled=true;btn.textContent='Собираем приглашение…';try{const [html,css,js]=await Promise.all([readText('index.html'),readText('styles.css'),readText('app.js')]);await Promise.all(Object.keys(c.photos).filter(k=>!k.endsWith('Alt')).map(async k=>{const src=c.photos[k];if(src.startsWith('data:'))return;const response=await fetch(src);if(!response.ok)throw Error('Не удалось загрузить фотографию: '+k);const blob=await response.blob();if(!blob.type.startsWith('image/'))throw Error('Ссылка '+k+' не содержит изображение.');c.photos[k]=await toData(blob);}));const close='</'+'script>';const inline=js.replace(/<\/script/gi,'<\\/script');const output=html.replace(/<link rel="stylesheet" href="styles.css">/,'<style>'+css+'\n.edit-link{display:none}</style>').replace(/<script src="content.js" defer><\/script>/,'<script>window.WEDDING = '+json(c)+';'+close).replace(/<script src="app.js" defer><\/script>/,'<script>'+inline+close).replace('<script>'+inline+close,'').replace('</body>','<script>'+inline+close+'</body>');download('invitation.html',output,'text/html;charset=utf-8');toast('Готово! invitation.html содержит фотографии и работает без интернета. Разместите его на хостинге как index.html.');}catch(error){toast(location.protocol==='file:'?'Для экспорта запустите Start-site.ps1 и откройте редактор через localhost.':'Не удалось собрать сайт. '+error.message+' Для внешних фото используйте загрузку с компьютера.');}finally{btn.disabled=false;btn.innerHTML=old;}});
draw();
})();
